	<div class="page-heading arena-detail-hero"><div><p class="eyebrow">Stage 1 · Dasar Bahasa Inggris</p><h1 class="h2">Kelas Bahasa Inggris</h1><p>12 bab · 60 pelajaran. Baca percakapan, pelajari pola dan kosakata, lalu berlatih. Evaluasi terbuka setelah pelajaran terkait selesai.</p><a class="btn btn-sun" href="<?php echo site_url('belajar/arena/riwayat'); ?>"><i class="bi bi-clock-history me-2" aria-hidden="true"></i>Riwayat saya</a></div><?php echo study_arena_art_tag('english'); ?></div>
	<?php $lessons = array_filter($packs, static function ($p) {
