		return (bool) $p['completed']; })); ?>
	<p class="alert alert-info"><?php echo $done; ?>/<?php echo count($lessons); ?> pelajaran pada pilihan ini ditinjau. Selesai meninjau bukan bukti penguasaan; hasil latihan dan evaluasi dicatat terpisah. Gunakan contoh tokoh rekaan saat latihan bicara.</p>
	<?php if ($running): ?><p><a class="btn btn-primary" href="<?php echo site_url('belajar/arena/main/'.$running['id']); ?>">Lanjutkan aktivitas yang belum selesai</a></p><?php endif; ?>
	<?php if ($settings['enabled'] !== '1' || $arena_settings['enabled'] !== '1'): ?><div class="alert alert-warning">Kelas sedang dijeda. Riwayat tersimpan tetap dapat dibaca.</div><?php else: ?>
	<div class="row g-3">
		<?php for ($chapter = 1; $chapter <= 12; $chapter++): $entries = array_values(array_filter($packs, static function ($p) use ($chapter) {
