		<div class="col-lg-6"><details class="feature-card h-100" id="bab-<?php echo $chapter; ?>"><summary class="h5 mb-0"><?php echo study_arena_art_tag('english', $entries[0]['chapter_title'], 'arena-chapter-art'); ?>Bab <?php echo $chapter; ?> · <?php echo html_escape($entries[0]['chapter_title']); ?><span class="d-block small text-secondary mt-2"><?php echo count(array_filter($entries, static function ($p) {
	return $p['kind'] === 'lesson' && $p['completed']; })); ?>/<?php echo count(array_filter($entries, static function($p){return $p['kind']==='lesson';})); ?> pelajaran ditinjau · buka rincian</span></summary><ul class="list-unstyled mt-3 mb-0">
			<?php foreach ($entries as $entry): ?><li class="border-top py-3"><strong class="d-block"><?php echo html_escape(explode(' · ', $entry['title'], 2)[1] ?? $entry['title']); ?></strong><span class="small d-block mb-2"><?php echo $entry['completed'] ? ($entry['kind'] === 'lesson' ? 'Sudah ditinjau' : ($entry['passed'] ? 'Ambang tercapai' : 'Sudah dicoba')) : 'Belum selesai'; ?><?php if ($entry['best_score'] !== NULL): ?> · terbaik <?php echo (int) $entry['best_score']; ?>%<?php endif; ?></span><?php if ($entry['enabled'] && $entry['unlocked']): ?><a class="btn btn-sm btn-outline-primary" href="<?php echo site_url('belajar/arena/pilih/'.$entry['slug']); ?>"><?php echo $entry['completed'] ? 'Tinjau lagi' : 'Mulai'; ?><span class="visually-hidden"> <?php echo html_escape($entry['title']); ?></span></a><?php else: ?><span class="text-secondary small"><?php echo ! $entry['enabled'] ? 'Dijeda pengelola' : 'Tinjau kelima pelajaran bab ini dahulu'; ?></span><?php endif; ?></li><?php endforeach; ?>
		</ul></details></div>
	<?php endfor; ?></div>
	<h2 class="h4 mt-5">Review dan evaluasi</h2><p>Ambang babak baru <?php echo (int) $settings['pass_score']; ?>%. Tanpa timer, bukan sertifikasi tingkat bahasa atau nilai sekolah.</p><div class="row g-3">
		<?php foreach ($packs as $entry): if ((int) $entry['chapter'] !== 0) { continue; } ?><div class="col-lg-4"><article class="feature-card h-100"><?php echo study_arena_art_tag('english', $entry['title']); ?><h3 class="h5"><?php echo html_escape($entry['title']); ?></h3><p><?php echo $entry['kind'] === 'final' ? '30 pertanyaan, setelah 60 pelajaran ditinjau.' : '20 pertanyaan, setelah 30 pelajaran pada enam bab terkait ditinjau.'; ?></p><?php if ($entry['best_score'] !== NULL): ?><p>Terbaik <?php echo (int) $entry['best_score']; ?>% · <?php echo $entry['passed'] ? 'Ambang tercapai' : 'Boleh mencoba lagi'; ?></p><?php endif; ?><?php if ($entry['enabled'] && $entry['unlocked']): ?><a class="btn btn-primary" href="<?php echo site_url('belajar/arena/pilih/'.$entry['slug']); ?>">Buka evaluasi<span class="visually-hidden"> <?php echo html_escape($entry['title']); ?></span></a><?php else: ?><p class="text-secondary"><?php echo $entry['enabled'] ? 'Selesaikan pelajaran terkait dahulu' : 'Dijeda pengelola'; ?></p><?php endif; ?></article></div><?php endforeach; ?></div>
	<?php endif; ?>
